use crate::common;
use rust_xlsxwriter::{Table, TableColumn, TableFunction, Workbook, XlsxError};

// Create a rust_xlsxwriter file to compare against an Excel file.
fn create_new_xlsx_file(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    worksheet.set_column_width(0, 14)?;
    worksheet.set_column_width(1, 14)?;

    worksheet.write(1, 0, 1)?;
    worksheet.write(2, 0, 2)?;
    worksheet.write(1, 1, 0)?;
    worksheet.write(2, 1, 0)?;

    let columns = vec![
        TableColumn::new()
            .set_header("a_x0041_b")
            .set_total_label("a_x0041_b"),
        TableColumn::new()
            .set_header("Foo")
            .set_total_function(TableFunction::Sum),
    ];

    let table = Table::new().set_columns(&columns).set_total_row(true);

    worksheet.add_table(0, 0, 3, 1, &table)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_escapes14() {
    let test_runner = common::TestRunner::new()
        .set_name("escapes14")
        .ignore_calc_chain()
        .set_function(create_new_xlsx_file)
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
